import type { Component } from '../component/component.js';
import type { Context } from './body.js';
import type { Declaration } from './declaration.js';
import type { Leaf } from './leaf.js';
import type { LinearComponent } from './linear.js';
import type { Name } from './name.js';

/**
 * How a render system's shaders reach its components: `accessors` names a WGSL function for each component it reads,
 * generated by `Gpu.wgsl` at bind group `group` (0 by default).
 */
export type Render = { readonly group?: number; readonly accessors: { readonly [name: string]: LinearComponent } };

/** One archetype the query matches, with rows `0` to `count`. `bind` sets the world's bind group for it on a pass. */
export type RenderTable = {
    readonly count: number;
    readonly bind: (pass: GPURenderPassEncoder | GPUComputePassEncoder) => void;
};

/**
 * What a render body records with. `encoder` is the run's: the world submits it, after the run's GPU kernels and
 * uploads, when the run ends. Acquire canvas textures inside the body.
 */
export type RenderContext = {
    readonly device: GPUDevice;
    readonly encoder: GPUCommandEncoder;
    readonly tables: readonly RenderTable[];
};

type RenderDeclaration = {
    readonly name: Name;
    /** It reads the components its accessors name. */
    readonly query?: { readonly read?: never; readonly has?: readonly Component.Name[]; readonly not?: readonly Component.Name[] };
    readonly resources?: Pick<NonNullable<Declaration["resources"]>, "read">;
    readonly render: Render;
    readonly before?: readonly Name[];
    readonly after?: readonly Name[];
    readonly during?: readonly Name[];
};

/** A render declaration with the components its accessors name as `query.read`. */
type Rendered<D extends RenderDeclaration> = D & { readonly query: { readonly read: readonly LinearComponent[] } };

/** A render system: a leaf whose work is `draw`, so its row body does nothing. */
export type RenderLeaf<D extends Declaration = Declaration> = Leaf<D> & { draw(gpu: RenderContext, context: Context<D>): void };

/**
 * Declares a render system: it runs once per run on the main thread, in schedule order, and records GPU work over
 * the GPU copy of the components its accessors name, which the world uploads first as needed. It needs a world with `gpu`.
 */
export const render = <const D extends RenderDeclaration>(
    declaration: D,
    draw: (gpu: RenderContext, context: Context<D>) => void,
): RenderLeaf<Rendered<D>> => ({
    declaration: { ...declaration, query: { ...declaration.query, read: [...new Set(Object.values(declaration.render.accessors))] } },
    body: () => {},
    draw,
});
